'use client'

import type { ComponentProps, ReactNode } from 'react'
import {
  Menu as UiMenu,
  MenuCheckboxItem as UiMenuCheckboxItem,
  MenuContent as UiMenuContent,
  MenuGroup as UiMenuGroup,
  MenuGroupLabel as UiMenuGroupLabel,
  MenuItem as UiMenuItem,
  MenuItemIcon as UiMenuItemIcon,
  MenuItemIndicator as UiMenuItemIndicator,
  MenuRadioGroup as UiMenuRadioGroup,
  MenuRadioItem as UiMenuRadioItem,
  MenuSeparator as UiMenuSeparator,
  MenuSub as UiMenuSub,
  MenuSubContent as UiMenuSubContent,
  MenuSubTrigger as UiMenuSubTrigger,
  MenuTrigger as UiMenuTrigger,
} from '@ui-sdk/react/menu'
import { createContext, useContext } from 'react'

import './menu.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

/**
 * Menu, a 1:1 port of opencode's Menu (`@opencode/ui`, MIT):
 * `packages/ui/src/navigation/menu` (`menu-v2`), on top of ui-sdk's headless
 * Menu.
 *
 * Styling lives in `menu.css` as attribute rules (`data-appearance`,
 * `data-variant`, `data-highlighted`, `data-checked`, `data-open`,
 * `data-disabled`), so rest, highlight, checked, expanded, disabled and the
 * submenu chevron match upstream. Behaviour (focus, arrow keys, typeahead,
 * dismissal, submenu timing, ARIA wiring) comes from `@ui-sdk/react`.
 *
 * Upstream's `appearance="standard"` reads opencode app-level tokens this repo
 * does not ship, so only the default `compact` look is ported. The item's
 * `badge` prop is not ported either: it is markup ui-sdk's item owns.
 */

export type MenuAppearance = 'compact'

export type MenuItemVariant = 'critical'

const MenuAppearanceContext = createContext<MenuAppearance>()

type UiMenuProps = ComponentProps<typeof UiMenu>

export type MenuProps = Omit<UiMenuProps, 'className' | 'render'> & {
  /** Defaults to `compact`, upstream's default. */
  appearance?: MenuAppearance
}

export function Menu(props: MenuProps) {
  const rest = omit(props, 'appearance')

  return (
    <MenuAppearanceContext.Provider value={props.appearance ?? 'compact'}>
      <UiMenu {...rest} />
    </MenuAppearanceContext.Provider>
  )
}

type UiMenuTriggerProps = ComponentProps<typeof UiMenuTrigger>

export type MenuTriggerProps = Omit<UiMenuTriggerProps, 'className' | 'render'> & {
  className?: UiMenuTriggerProps['className']
  render?: UiMenuTriggerProps['render']
}

export function MenuTrigger(props: MenuTriggerProps) {
  const rest = omit(props, 'className', 'render')

  return <UiMenuTrigger {...rest} className={props.className} render={props.render} />
}

type UiMenuContentProps = ComponentProps<typeof UiMenuContent>

export type MenuContentProps = Omit<UiMenuContentProps, 'className' | 'render'> & {
  className?: UiMenuContentProps['className']
  render?: UiMenuContentProps['render']
}

export function MenuContent(props: MenuContentProps) {
  const appearance = useContext(MenuAppearanceContext) ?? 'compact'
  const rest = omit(props, 'className', 'render')

  return (
    <UiMenuContent
      {...rest}
      className={props.className}
      render={props.render}
      data-appearance={appearance}
    />
  )
}

/** The submenu's popup, styled and marked exactly like the root content. */
export function MenuSubContent(props: MenuContentProps) {
  const appearance = useContext(MenuAppearanceContext) ?? 'compact'
  const rest = omit(props, 'className', 'render')

  return (
    <UiMenuSubContent
      {...rest}
      className={props.className}
      render={props.render}
      data-appearance={appearance}
    />
  )
}

type UiMenuItemProps = ComponentProps<typeof UiMenuItem>

export type MenuItemProps = Omit<
  UiMenuItemProps,
  'className' | 'render' | 'children'
> & {
  /** Upstream's `data-variant="critical"`, a destructive action. */
  variant?: MenuItemVariant
  className?: UiMenuItemProps['className']
  render?: UiMenuItemProps['render']
  children?: UiMenuItemProps['children']
}

export function MenuItem(props: MenuItemProps) {
  const rest = omit(props, 'className', 'render', 'variant', 'children')

  return (
    <UiMenuItem
      {...rest}
      className={props.className}
      render={props.render}
      data-variant={props.variant ?? (props.destructive ? 'critical' : undefined)}
    >
      {(state) => (
        <span data-slot="menu-item-content">
          {typeof props.children === 'function'
            ? props.children(state)
            : props.children}
        </span>
      )}
    </UiMenuItem>
  )
}

type UiMenuCheckboxItemProps = ComponentProps<typeof UiMenuCheckboxItem>

export type MenuCheckboxItemProps = Omit<
  UiMenuCheckboxItemProps,
  'className' | 'render' | 'children'
> & {
  variant?: MenuItemVariant
  className?: UiMenuCheckboxItemProps['className']
  render?: UiMenuCheckboxItemProps['render']
  children?: UiMenuCheckboxItemProps['children']
}

export function MenuCheckboxItem(props: MenuCheckboxItemProps) {
  const rest = omit(props, 'className', 'render', 'variant', 'children')

  return (
    <UiMenuCheckboxItem
      {...rest}
      className={props.className}
      render={props.render}
      data-variant={props.variant}
    >
      {(state) => (
        <>
          <span data-slot="menu-item-content">
            {typeof props.children === 'function'
              ? props.children(state)
              : props.children}
          </span>
          <UiMenuItemIndicator keepMounted>
            <CheckMark />
          </UiMenuItemIndicator>
        </>
      )}
    </UiMenuCheckboxItem>
  )
}

type UiMenuRadioGroupProps = ComponentProps<typeof UiMenuRadioGroup>

export type MenuRadioGroupProps = Omit<
  UiMenuRadioGroupProps,
  'className' | 'render'
> & {
  className?: UiMenuRadioGroupProps['className']
  render?: UiMenuRadioGroupProps['render']
}

export function MenuRadioGroup(props: MenuRadioGroupProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiMenuRadioGroup {...rest} className={props.className} render={props.render} />
  )
}

type UiMenuRadioItemProps = ComponentProps<typeof UiMenuRadioItem>

export type MenuRadioItemProps = Omit<
  UiMenuRadioItemProps,
  'className' | 'render' | 'children'
> & {
  variant?: MenuItemVariant
  className?: UiMenuRadioItemProps['className']
  render?: UiMenuRadioItemProps['render']
  children?: UiMenuRadioItemProps['children']
}

export function MenuRadioItem(props: MenuRadioItemProps) {
  const rest = omit(props, 'className', 'render', 'variant', 'children')

  return (
    <UiMenuRadioItem
      {...rest}
      className={props.className}
      render={props.render}
      data-variant={props.variant}
    >
      {(state) => (
        <>
          <span data-slot="menu-item-content">
            {typeof props.children === 'function'
              ? props.children(state)
              : props.children}
          </span>
          <UiMenuItemIndicator keepMounted>
            <CheckMark />
          </UiMenuItemIndicator>
        </>
      )}
    </UiMenuRadioItem>
  )
}

type UiMenuGroupProps = ComponentProps<typeof UiMenuGroup>

export type MenuGroupProps = Omit<UiMenuGroupProps, 'className' | 'render'> & {
  className?: UiMenuGroupProps['className']
  render?: UiMenuGroupProps['render']
}

export function MenuGroup(props: MenuGroupProps) {
  const rest = omit(props, 'className', 'render')

  return <UiMenuGroup {...rest} className={props.className} render={props.render} />
}

type UiMenuGroupLabelProps = ComponentProps<typeof UiMenuGroupLabel>

export type MenuGroupLabelProps = Omit<
  UiMenuGroupLabelProps,
  'className' | 'render'
> & {
  className?: UiMenuGroupLabelProps['className']
  render?: UiMenuGroupLabelProps['render']
}

export function MenuGroupLabel(props: MenuGroupLabelProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiMenuGroupLabel {...rest} className={props.className} render={props.render} />
  )
}

type UiMenuSeparatorProps = ComponentProps<typeof UiMenuSeparator>

export type MenuSeparatorProps = Omit<
  UiMenuSeparatorProps,
  'className' | 'render'
> & {
  className?: UiMenuSeparatorProps['className']
  render?: UiMenuSeparatorProps['render']
}

export function MenuSeparator(props: MenuSeparatorProps) {
  const rest = omit(props, 'className', 'render')

  return <UiMenuSeparator {...rest} className={props.className} render={props.render} />
}

type UiMenuItemIconProps = ComponentProps<typeof UiMenuItemIcon>

export type MenuItemIconProps = Omit<UiMenuItemIconProps, 'className' | 'render'> & {
  className?: UiMenuItemIconProps['className']
  render?: UiMenuItemIconProps['render']
}

export function MenuItemIcon(props: MenuItemIconProps) {
  const rest = omit(props, 'className', 'render')

  return <UiMenuItemIcon {...rest} className={props.className} render={props.render} />
}

type UiMenuSubProps = ComponentProps<typeof UiMenuSub>

export type MenuSubProps = UiMenuSubProps

export function MenuSub(props: MenuSubProps) {
  return <UiMenuSub {...props} />
}

type UiMenuSubTriggerProps = ComponentProps<typeof UiMenuSubTrigger>

export type MenuSubTriggerProps = Omit<
  UiMenuSubTriggerProps,
  'className' | 'render' | 'children'
> & {
  className?: UiMenuSubTriggerProps['className']
  render?: UiMenuSubTriggerProps['render']
  children?: UiMenuSubTriggerProps['children']
}

export function MenuSubTrigger(props: MenuSubTriggerProps) {
  const rest = omit(props, 'className', 'render', 'children')

  return (
    <UiMenuSubTrigger {...rest} className={props.className} render={props.render}>
      {(state) => (
        <>
          <span data-slot="menu-item-content">
            {typeof props.children === 'function'
              ? props.children(state)
              : props.children}
          </span>
          <ChevronRight />
        </>
      )}
    </UiMenuSubTrigger>
  )
}

/** Upstream's trailing chevron for a submenu trigger. */
function ChevronRight() {
  return (
    <svg
      data-slot="menu-item-chevron"
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path d="M6 4L10 8L6 12V4Z" fill="currentColor" />
    </svg>
  )
}

/** Upstream's check mark inside a checkbox or radio item. */
function CheckMark(): ReactNode {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M3.53564 8.17857L6.39279 11.75L12.4642 4.25"
        stroke="currentColor"
        strokeWidth="1"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/*
 * 1:1 port of opencode's Menu (`@opencode/ui`, MIT):
 * packages/ui/src/navigation/menu/menu.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so rest / highlight / checked / expanded / disabled and the
 * submenu chevron match `data-component="menu-v2-content"`:
 *
 *   [data-component="menu-v2-content"]   →  [data-slot="menu-content"][data-appearance="compact"]
 *   [data-component="menu-v2-item"]      →  the item slots (ui-sdk splits them
 *                                            into menu-item, menu-checkbox-item,
 *                                            menu-radio-item and the submenu's
 *                                            menu-trigger)
 *   [data-slot="menu-v2-item-content"]   →  [data-slot="menu-item-content"]
 *   [data-slot="menu-v2-item-shortcut"]  →  [data-slot="menu-shortcut"]  (ui-sdk's own part)
 *   [data-slot="menu-v2-item-indicator"] →  [data-slot="menu-item-indicator"]
 *   [data-slot="menu-v2-item-chevron"]   →  [data-slot="menu-item-chevron"]
 *   [data-slot="menu-v2-separator"]      →  [data-slot="menu-separator"]
 *   [data-slot="menu-v2-group-label"]    →  [data-slot="menu-group-label"]
 *   [data-expanded] on a submenu trigger →  [data-open]  (ui-sdk's attribute)
 *
 * Upstream positions the popup in a `[data-popper-positioner]` wrapper and
 * raises it with `z-index: 60`. ui-sdk renders the popup in place in the top
 * layer, with no positioner element, so the content is its own positioner and
 * keeps that z-index directly.
 *
 * `appearance="standard"` is not ported: it reads opencode's app-level tokens
 * (--surface-raised-*, --shadow-md, --text-*, --icon-base,
 * --font-size-x-small) that src/theme.css does not ship. Only `compact`,
 * upstream's default, is here. The item `badge` slot is not ported either: it
 * belongs to markup ui-sdk's item owns.
 *
 * menu.css has no [data-color-scheme="dark"] block; the --v2-* tokens flip
 * with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="menu-content"][data-appearance="compact"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    padding: 2px;
    min-width: 160px;
    z-index: 60;
    pointer-events: auto;

    background: var(--v2-background-bg-layer-01);
    border-radius: 6px;
    box-shadow: var(--v2-elevation-floating);

    outline: none;

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
  }

  [data-slot="menu-content"][data-appearance="compact"]:focus-visible {
    outline: none;
  }

  :dir(rtl) [data-slot="menu-item-chevron"] {
    transform: scaleX(-1);
  }

  /*
   * Upstream marks plain, checkbox and radio items with one attribute,
   * `data-component="menu-v2-item"`, and does the same for a submenu trigger.
   * ui-sdk gives each its own slot, so every rule below lists all four.
   */
  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    ) {
    --menu-v2-fg: var(--v2-text-text-base);
    --menu-v2-fg-muted: var(--v2-text-text-faint);
    --menu-v2-fg-subtle: var(--v2-text-text-muted);
    --menu-v2-icon: var(--v2-icon-icon-base);
    --menu-v2-hover: var(--v2-overlay-simple-overlay-hover);

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;

    box-sizing: border-box;
    display: flex;
    flex-shrink: 0;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    height: 28px;
    padding: 0 12px;
    padding-inline-end: 6px;
    background: transparent;
    border-radius: 4px;
    outline: none;
    cursor: default;
    user-select: none;

    font-variation-settings: "slnt" 0;
    font-variant-numeric: tabular-nums;
    color: var(--menu-v2-fg);
  }

  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    )[data-variant="critical"] {
    --menu-v2-fg: var(--v2-state-fg-danger);
  }

  [data-slot="menu-item-content"] {
    display: flex;
    flex: 1 1 auto;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    min-width: 0;

    font-size: 13px;
    font-weight: 440;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--menu-v2-fg);
  }

  [data-slot="menu-shortcut"] {
    display: inline-flex;
    align-items: center;
    flex: none;
    height: 11px;

    font-size: 11px;
    font-weight: 530;
    line-height: 100%;
    letter-spacing: 0.05px;
    color: var(--menu-v2-fg-muted);
    white-space: nowrap;
  }

  [data-slot="menu-item-indicator"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 16px;
    height: 16px;
    color: var(--menu-v2-icon);
  }

  [data-slot="menu-item-indicator"]:not([data-checked]) > svg {
    visibility: hidden;
  }

  [data-slot="menu-item-chevron"] {
    flex: none;
    width: 16px;
    height: 16px;
    color: var(--menu-v2-fg-muted);
  }

  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    )[data-highlighted] {
    background: var(--menu-v2-hover);
  }

  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    )[data-checked] [data-slot="menu-item-content"] {
    font-weight: 440;
    color: var(--menu-v2-fg);
  }

  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    )[data-checked] [data-slot="menu-item-indicator"] {
    color: var(--menu-v2-icon);
  }

  :is(
      [data-slot="menu-item"],
      [data-slot="menu-checkbox-item"],
      [data-slot="menu-radio-item"],
      [data-slot="menu-content"] [data-slot="menu-trigger"]
    )[data-disabled] {
    pointer-events: none;
    opacity: 0.5;
  }

  /* Like a native menu, an item stays highlighted while the pointer is in the submenu it opened. */
  [data-slot="menu-content"][data-appearance="compact"]:not(:has([data-highlighted]))
    [data-slot="menu-trigger"][data-open] {
    background: var(--menu-v2-hover);
  }

  [data-slot="menu-separator"] {
    height: 1px;
    width: calc(100% + 4px);
    margin: 2px -2px;
    background: var(--v2-border-border-muted);
    border: none;
  }

  [data-slot="menu-group-label"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    height: 28px;
    padding: 0 12px;

    font-size: 11px;
    font-weight: 530;
    letter-spacing: 0.05px;
    color: var(--v2-text-text-faint);
    user-select: none;
    font-variant-numeric: tabular-nums;
  }
}
